// The shipped sound files (public/sfx, generated by scripts/audio/pack-sfx.mjs) against their source (audio-src/sfx):
// what each toy downloads, that no clip is downloaded twice, and that only a clip's place in the file changed.
// (Sample-level identity is checked by `npm run check:sfx`; the routing tests in fidgetAudio.test.ts play from these files.)
import { describe, expect, it } from "vitest";
import { SFX_FIDGET_CHUNKS, SFX_FIDGET_TOYS, SFX_KEYBOARD, SFX_SQUISHY } from "../src/audio/sfxManifest";
import { FIDGET_SOUND, MIX_SOUND, WAX_STAGES, type PoolRef } from "../src/toys/fidgets/soundBank";
import { FIDGETS } from "../src/toys/fidgets/catalog";

const fsName = "node:fs", cryptoName = "node:crypto";
const fs = (await import(/* @vite-ignore */ fsName)) as { readFileSync(p: URL): Uint8Array; existsSync(p: URL): boolean; readdirSync(p: URL, o: { recursive: true }): string[] };
const crypto = (await import(/* @vite-ignore */ cryptoName)) as { createHash(a: string): { update(b: Uint8Array): { digest(e: "hex"): string } } };
const pub = (p: string) => new URL(`../public/${p}`, import.meta.url);
const json = (u: URL) => JSON.parse(new TextDecoder().decode(fs.readFileSync(u)));
interface Entry { start: number; length: number; offset: number; duration: number; gain: number; src: string; [k: string]: unknown }
interface Sprite { file: string; toys?: string[]; sources: Record<string, unknown>; pools: Record<string, { entries: Entry[]; [k: string]: unknown }> }
const source = (s: string): Sprite => json(new URL(`../audio-src/sfx/fidgets/${s}.json`, import.meta.url));
const chunk = (n: string): Sprite => json(pub(SFX_FIDGET_CHUNKS[n].json));
const refsOf = (id: string): PoolRef[] => [...Object.values(FIDGET_SOUND[id] ?? {}), ...Object.values(MIX_SOUND[id] ?? {}), ...Object.values(WAX_STAGES[id] ?? {})].filter(Boolean) as PoolRef[];

describe("shipped sound files", () => {
  it("every file in the manifest exists and its name carries the hash of its content", () => {
    const all = [...Object.values(SFX_KEYBOARD), SFX_SQUISHY, ...Object.values(SFX_FIDGET_CHUNKS)].flatMap((f) => [f.json, f.audio]);
    for (const p of all) {
      const bytes = fs.readFileSync(pub(p));
      expect(p, p).toMatch(/\.[0-9a-f]{10}\.(json|flac)$/);
      expect(p.split(".").slice(-2)[0], p).toBe(crypto.createHash("sha256").update(bytes).digest("hex").slice(0, 10));
      if (p.endsWith(".flac")) expect(String.fromCharCode(...bytes.subarray(0, 4)), p).toBe("fLaC");
    }
  });

  it("public/sfx holds no WAV (sources stay in audio-src/)", () => {
    const files = fs.readdirSync(pub("sfx"), { recursive: true });
    expect(files.filter((f) => /\.wav$/i.test(f))).toEqual([]);
  });

  it("each fidget toy loads exactly the chunks holding its pools, and every pool it plays is in them", () => {
    for (const f of FIDGETS.filter((f) => !f.soundAs)) { // (the 뭉개기 toys borrow these: catalog soundAs)
      const names = SFX_FIDGET_TOYS[f.id] ?? [];
      expect(names.length, f.id).toBeGreaterThan(0);
      for (const n of names) expect(chunk(n).toys, n).toContain(f.id);
      for (const r of refsOf(f.id))
        for (const pool of [r.pool, r.alt?.pool].filter(Boolean) as string[]) {
          if (!source(r.source).pools[pool]) continue; // dropped by the clip audit: silent before as well
          const holders = names.filter((n) => n.startsWith(r.source + ".") && chunk(n).pools[pool]);
          expect(holders, `${f.id} ${r.source}/${pool}`).toHaveLength(1);
        }
    }
  });

  it("no clip ships twice: a pool shared by several toys lives in one shared chunk", () => {
    const seen = new Map<string, string>();
    for (const n of Object.keys(SFX_FIDGET_CHUNKS))
      for (const pool of Object.keys(chunk(n).pools)) {
        const key = `${n.split(".")[0]}/${pool}`;
        expect(seen.get(key), `${key} in ${n} and ${seen.get(key)}`).toBeUndefined();
        seen.set(key, n);
      }
  });

  it("repacking moves clips only: same order, length, duration, gain, source and metadata; the move is a multiple of 40 ms", () => {
    for (const n of Object.keys(SFX_FIDGET_CHUNKS)) {
      const c = chunk(n), s = source(n.split(".")[0]);
      const sr = (c as unknown as { sampleRate: number }).sampleRate;
      for (const [pool, meta] of Object.entries(c.pools)) {
        const orig = s.pools[pool];
        expect(meta.entries.length, `${n}/${pool}`).toBe(orig.entries.length);
        const { entries: _a, ...metaRest } = meta, { entries: _b, ...origRest } = orig;
        expect(metaRest).toEqual(origRest);
        meta.entries.forEach((e, i) => {
          const o = orig.entries[i];
          const { start, offset, ...rest } = e, { start: os, offset: oo, ...orest } = o;
          expect(rest, `${n}/${pool}#${i}`).toEqual(orest);
          expect(Math.abs((start - os) % (sr / 25)), `${n}/${pool}#${i} shift`).toBe(0);
          expect(offset - oo).toBeCloseTo((start - os) / sr, 6);
        });
      }
      for (const id of Object.keys(c.sources)) expect(c.sources[id]).toEqual(s.sources[id]);
    }
  });

  it("keyboard / squishy maps are the source maps with only the file name changed", () => {
    for (const [id, f] of Object.entries(SFX_KEYBOARD)) {
      const { file, ...rest } = json(pub(f.json)), { file: srcFile, ...srcRest } = json(new URL(`../audio-src/sfx/keyboard/${id}.json`, import.meta.url));
      expect(rest, id).toEqual(srcRest);
      expect(srcFile).toBe(`${id}.wav`);
      expect(f.audio.endsWith(file)).toBe(true);
    }
    const { file, ...rest } = json(pub(SFX_SQUISHY.json)), { file: _f, ...srcRest } = json(new URL("../audio-src/sfx/squishy/squishy.json", import.meta.url));
    expect(rest).toEqual(srcRest);
    expect(SFX_SQUISHY.audio.endsWith(file)).toBe(true);
  });
});
